class Solution { public int findTargetSumWays(int[] nums,int target){Map<Integer,Integer> ways=new HashMap<>();ways.put(0,1);for(int value:nums){Map<Integer,Integer> next=new HashMap<>();for(Map.Entry<Integer,Integer> entry:ways.entrySet()){next.merge(entry.getKey()+value,entry.getValue(),Integer::sum);next.merge(entry.getKey()-value,entry.getValue(),Integer::sum);}ways=next;}return ways.getOrDefault(target,0);} }
